# -*- coding: utf-8 -*-
"""R74 S9 blind predictions generator: B23 + B25 (27 cases).
Writes each prediction file exactly by id list, with per-batch assertions.
Trigger convention used in reasons (no written definition in method text;
recorded honestly per case): changed_main = final main direction was changed
after裁决表/扫查复核 vs surface reading; reserve_used = main用神 had to be
taken from a reserve source (变爻/日月/伏神) instead of现卦同亲;
disputed = 取用两现难分 or direction genuinely two-readable.
Non-liuyao cases: all three false, reason "".
"""
import json, pathlib

OUT = pathlib.Path("/home/hatch/workspace/divination/benchmark/phase3/runs/round74/predictions")
OUT.mkdir(parents=True, exist_ok=True)

def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

def write_batch(batch_name, expected_ids, preds):
    assert [p["case_id"] for p in preds] == expected_ids, (batch_name, [p["case_id"] for p in preds])
    for p in preds:
        assert set(p.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, p["case_id"]
        assert 0.0 <= p["confidence"] <= 1.0
        fp = OUT / (p["case_id"] + ".json")
        fp.write_text(json.dumps(p, ensure_ascii=False, indent=1), encoding="utf-8")
        back = json.loads(fp.read_text(encoding="utf-8"))
        assert back["case_id"] == p["case_id"]
    print(batch_name, "wrote", len(preds), "ids ok")

